  .mobile-pad {
    display: block;
    left: max(18px, env(safe-area-inset-left));
    bottom: calc(76px + env(safe-area-inset-bottom));
    width: 154px;
    height: 154px;
    touch-action: none;
  }
  .mobile-pad button {
    width: 48px;
    height: 48px;
    font-size: 21px;
    -webkit-tap-highlight-color: transparent;
  }
  .mobile-pad [data-dir=up] { left: 53px; top: 0; }
  .mobile-pad [data-dir=left] { left: 0; top: 53px; }
  .mobile-pad [data-dir=down] { left: 53px; top: 53px; transform: translateY(53px); }
  .mobile-pad [data-dir=right] { left: 106px; top: 53px; }
  .mobile-interact {
    position: absolute;
    z-index: 4;
    display: grid;
    place-content: center;
    gap: 2px;
    right: max(24px, env(safe-area-inset-right));
    bottom: calc(94px + env(safe-area-inset-bottom));
    width: 76px;
    height: 76px;
    border: 1px solid rgba(255,255,255,.62);
    border-radius: 50%;
    background: rgba(20,52,50,.78);
    color: #f7f2e8;
    font: 500 10px/1 'DM Mono', monospace;
    letter-spacing: 1px;
    text-align: center;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    backdrop-filter: blur(8px);
  }
  .mobile-interact b { color: var(--gold); font-size: 16px; }
  .mobile-interact:active, .mobile-pad button:active { background: rgba(233,182,91,.86); color: #173a36; }
  .right-controls { right: max(22px, env(safe-area-inset-right)); bottom: calc(16px + env(safe-area-inset-bottom)); }
  .location-tag { bottom: calc(18px + env(safe-area-inset-bottom)); }
}

